1	<?php
2	
3	namespace App\Services\Batch;
4	
5	use App\Models\PointGrantWaiting;
6	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException;
7	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\AllianceUserNotFoundException;
8	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\AlreadyGrantedException;
9	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\PointDuplicateException;
10	use App\Services\Common\Ecnavi\InternalApi\Exceptions\ForbiddenException;
11	use App\Services\Common\Ecnavi\InternalApi\Exceptions\InternalServerErrorException;
12	use App\Services\Common\Ecnavi\InternalApi\Exceptions\MethodNotAllowedException;
13	use App\Services\Common\Ecnavi\InternalApi\Exceptions\UnauthorizedException;
14	use App\Services\Common\Ecnavi\InternalApi\Exceptions\UnexpectedException;
15	use App\Services\Common\Ecnavi\InternalApiService;
16	use App\States\PointGrantWaiting\Granted;
17	use App\States\PointGrantWaiting\Rejected;
18	use App\States\PointGrantWaiting\Waiting;
19	use Psr\Log\LoggerInterface;
20	use Throwable;
21	
22	class GrantPointsService
23	{
24	    public function __construct(
25	        private readonly InternalApiService $internalApiService,
26	        private readonly LoggerInterface $logger
27	    ) {
28	    }
29	
30	    public function grantPoints(): void
31	    {
32	        $waitings = PointGrantWaiting::whereState('status', Waiting::class)->limit(1500)->orderBy('id', 'asc')->get();
33	        $this->logger->info('ポイント付与リクエストを開始します。');
34	        $this->logger->info(sprintf('ポイント付与リクエスト数: %d', count($waitings)));
35	        $errorCount = 0;
36	        foreach ($waitings as $waiting) {
37	            try {
38	                $grantId = "ORSAY_{$waiting->id}";
39	                $this->internalApiService->grant($grantId, $waiting->point_id, $waiting->user_id, $waiting->point_value);
40	                $waiting->status->transitionTo(Granted::class);
41	            } catch (AlreadyGrantedException $e) {
42	                $this->logger->info("既にポイント付与済みのためポイント付与済みステータスに倒します。grantId: {$grantId}, point_grant_waitings.id: {$waiting->id}, message: {$e->getMessage()}");
43	                $waiting->status->transitionTo(Granted::class);
44	            } catch (PointDuplicateException $e) {
45	                $this->logger->info("過去に同じユーザに同じポイントIDでポイントが付与されていたためポイント付与は行わず却下します。grantId: {$grantId}, point_grant_waitings.id: {$waiting->id}, message: {$e->getMessage()}");
46	                $waiting->status->transitionTo(Rejected::class);
47	            } catch (AllianceUserNotFoundException $e) {
48	                $this->logger->info("退会済みなどの理由によりユーザーが存在しないためポイント付与は行わず却下します。grantId: {$grantId}, point_grant_waitings.id: {$waiting->id}, message: {$e->getMessage()}");
49	                $waiting->status->transitionTo(Rejected::class);
50	            } catch (BadRequestException $e) {
51	                $this->logger->warning("リクエスト内容が誤っているためECナビへのポイント付与リクエストが失敗しました。grantId: {$grantId}, point_grant_waitings.id: {$waiting->id}, message: {$e->getMessage()}", ['error' => "$e"]);
52	                $errorCount++;
53	            } catch (UnauthorizedException $e) {
54	                $this->logger->warning("認証エラーのためECナビへのポイント付与リクエストが失敗しました。grantId: {$grantId}, point_grant_waitings.id: {$waiting->id}, message: {$e->getMessage()}", ['error' => "$e"]);
55	                $errorCount++;
56	            } catch (ForbiddenException $e) {
57	                $this->logger->warning("アクセス権限エラーのためECナビへのポイント付与リクエストが失敗しました。grantId: {$grantId}, point_grant_waitings.id: {$waiting->id}, message: {$e->getMessage()}", ['error' => "$e"]);
58	                $errorCount++;
59	            } catch (MethodNotAllowedException $e) {
60	                $this->logger->warning("リクエストメソッドエラーのためECナビへのポイント付与リクエストが失敗しました。grantId: {$grantId}, point_grant_waitings.id: {$waiting->id}, message: {$e->getMessage()}", ['error' => "$e"]);
61	                $errorCount++;
62	            } catch (InternalServerErrorException $e) {
63	                $this->logger->warning("ECナビ側のサーバエラーのためECナビへのポイント付与リクエストが失敗しました。grantId: {$grantId}, point_grant_waitings.id: {$waiting->id}, message: {$e->getMessage()}", ['error' => "$e"]);
64	                $errorCount++;
65	            } catch (UnexpectedException $e) {
66	                $this->logger->warning("ECナビから予期せぬレスポンスが返ってきたためECナビへのポイント付与リクエストが失敗しました。grantId: {$grantId}, point_grant_waitings.id: {$waiting->id}, message: {$e->getMessage()}", ['error' => "$e"]);
67	                $errorCount++;
68	            } catch (Throwable $e) {
69	                $this->logger->warning("予期せぬエラーによりECナビへのポイント付与リクエストが失敗しました。grantId: {$grantId}, point_grant_waitings.id: {$waiting->id}, message: {$e->getMessage()}", ['error' => "$e"]);
70	                throw $e; // 予期せぬエラーのため例外を投げてバッチの実行自体を失敗とする
71	            }
72	        }
73	        if ($errorCount > 0) {
74	            $this->logger->warning(sprintf('%d件のポイント付与リクエストが失敗しました。失敗した分は次回バッチ実行時に拾われます。', $errorCount));
75	        }
76	        $this->logger->info('ポイント付与リクエストを終了します。');
77	    }
78	}
