3	namespace App\Services\Common\Ecnavi;
4	
5	use App\Services\Common\Ecnavi\InternalApi\Client;
6	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\AllianceUserNotFoundException;
7	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\AlreadyGrantedException;
8	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\ClientNotFoundException;
9	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\InvalidParameterException;
10	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\MaxPointValueException;
11	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\PointDuplicateException;
12	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\PointIdNotFoundException;
13	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\TemplateNotFoundException;
14	use App\Services\Common\Ecnavi\InternalApi\Exceptions\ForbiddenException;
15	use App\Services\Common\Ecnavi\InternalApi\Exceptions\InternalServerErrorException;
16	use App\Services\Common\Ecnavi\InternalApi\Exceptions\MethodNotAllowedException;
17	use App\Services\Common\Ecnavi\InternalApi\Exceptions\NotFoundException;
18	use App\Services\Common\Ecnavi\InternalApi\Exceptions\ServiceUnavailableException;
19	use App\Services\Common\Ecnavi\InternalApi\Exceptions\UnauthorizedException;
20	use App\Services\Common\Ecnavi\InternalApi\Exceptions\UnexpectedException;
21	use Illuminate\Support\Facades\App;
22	use Illuminate\Support\Facades\Config;
23	
24	class InternalApiService
25	{
26	    const CREATE_POINT_ID_PATH = '/createPointId';
27	
28	    const GRANT_PATH = '/grant';
29	
30	    // ポイント数は Orsay 管理画面のみで管理するためECナビのポイントIDは0ポイントで作成する
31	    private const POINT_VALUE = 0;
32	
33	    public function __construct(private readonly Client $client)
34	    {
35	    }
36	
37	    /**
38	     * @throws \JsonException
39	     * @throws InvalidParameterException
40	     * @throws TemplateNotFoundException
41	     * @throws ClientNotFoundException
42	     * @throws PointDuplicateException
43	     * @throws MaxPointValueException
44	     * @throws AllianceUserNotFoundException
45	     * @throws PointIdNotFoundException
46	     * @throws AlreadyGrantedException
47	     * @throws UnauthorizedException
48	     * @throws ForbiddenException
49	     * @throws NotFoundException
50	     * @throws MethodNotAllowedException
51	     * @throws InternalServerErrorException
52	     * @throws ServiceUnavailableException
53	     * @throws UnexpectedException
54	     */
55	    public function createPointId(string $pointName, string $pointShowName): int
56	    {
57	        $params = [
58	            // TODO: アンケートの種類によって適切なtemplateIdが決まるはず。決まったら修正する
59	            'templateId' => (int) Config::string('ecnavi.app.internal_api.template_id'),
60	            'pointValue' => self::POINT_VALUE,
61	            'pointName' => $pointName,
62	            'pointShowName' => $pointShowName,
63	        ];
64	
65	        // ローカル環境のみAPIレスポンスを偽装する
66	        $result = App::environment(['local']) ? [
67	            'statusCode' => 200,
68	            'body' => [
69	                'pointId' => random_int(1, 1000000000),
70	                'message' => 'ポイントID作成成功',
71	            ],
72	        ] : $this->client->post(self::CREATE_POINT_ID_PATH, $params);
73	
74	        return $result['body']['pointId'];
75	    }
76	
77	    /**
78	     * @throws \JsonException
79	     * @throws InvalidParameterException
80	     * @throws TemplateNotFoundException
81	     * @throws ClientNotFoundException
82	     * @throws PointDuplicateException
83	     * @throws MaxPointValueException
84	     * @throws AllianceUserNotFoundException
85	     * @throws PointIdNotFoundException
86	     * @throws AlreadyGrantedException
87	     * @throws UnauthorizedException
88	     * @throws ForbiddenException
89	     * @throws NotFoundException
90	     * @throws MethodNotAllowedException
91	     * @throws InternalServerErrorException
92	     * @throws ServiceUnavailableException
93	     * @throws UnexpectedException
94	     */
95	    public function grant(string $grantId, int $pointId, int $allianceUserId, int $pointValue): void
96	    {
97	        $params = [
98	            'grantId' => $grantId,
99	            'pointId' => $pointId,
100	            'allianceUserId' => $allianceUserId,
101	            'pointValue' => $pointValue,
102	        ];
103	
104	        // ローカル環境のみAPIレスポンスを偽装する
105	        if (! App::environment(['local'])) {
106	            $this->client->post(self::GRANT_PATH, $params);
107	        }
108	    }
109	}
