3	namespace App\Services\Common\Ecnavi\InternalApi;
4	
5	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\AllianceUserNotFoundException;
6	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\AlreadyGrantedException;
7	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\ClientNotFoundException;
8	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\InvalidParameterException;
9	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\MaxPointValueException;
10	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\PointDuplicateException;
11	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\PointIdNotFoundException;
12	use App\Services\Common\Ecnavi\InternalApi\Exceptions\BadRequestException\TemplateNotFoundException;
13	use App\Services\Common\Ecnavi\InternalApi\Exceptions\ForbiddenException;
14	use App\Services\Common\Ecnavi\InternalApi\Exceptions\InternalServerErrorException;
15	use App\Services\Common\Ecnavi\InternalApi\Exceptions\MethodNotAllowedException;
16	use App\Services\Common\Ecnavi\InternalApi\Exceptions\NotFoundException;
17	use App\Services\Common\Ecnavi\InternalApi\Exceptions\ServiceUnavailableException;
18	use App\Services\Common\Ecnavi\InternalApi\Exceptions\UnauthorizedException;
19	use App\Services\Common\Ecnavi\InternalApi\Exceptions\UnexpectedException;
20	use Illuminate\Http\Client\PendingRequest;
21	use Illuminate\Http\Client\Response;
22	use Illuminate\Support\Facades\Config;
23	use Illuminate\Support\Facades\Http;
24	
25	readonly class Client
26	{
27	    const ECNAVI_INTERNAL_API_PATH = '/api/internal/point/v1';
28	
29	    private PendingRequest $client;
30	
31	    /** @var array<mixed> */
32	    private array $defaultParameters;
33	
34	    public function __construct(private Signature $signature)
35	    {
36	        $this->client = Http::baseUrl(Config::string('ecnavi.app.base_url'));
37	        $this->defaultParameters = [
38	            'clientId' => (int) Config::string('ecnavi.app.internal_api.client_id'),
39	        ];
40	    }
41	
42	    /**
43	     * @param  array<mixed>  $params
44	     * @param  array<mixed>  $options
45	     * @return array{statusCode: int, body: array{pointId: int, message: string}}
46	     * @throws \JsonException
47	     * @throws InvalidParameterException
48	     * @throws TemplateNotFoundException
49	     * @throws ClientNotFoundException
50	     * @throws PointDuplicateException
51	     * @throws MaxPointValueException
52	     * @throws AllianceUserNotFoundException
53	     * @throws PointIdNotFoundException
54	     * @throws AlreadyGrantedException
55	     * @throws UnauthorizedException
56	     * @throws ForbiddenException
57	     * @throws NotFoundException
58	     * @throws MethodNotAllowedException
59	     * @throws InternalServerErrorException
60	     * @throws ServiceUnavailableException
61	     * @throws UnexpectedException
62	     */
63	    public function post(string $path, array $params, array $options = []): array
64	    {
65	        $requestParams = [...$this->defaultParameters, ...$params];
66	        $signature = $this->signature->generate($requestParams);
67	
68	        $response = $this->client
69	            ->retry(
70	                (int) Config::string('ecnavi.app.internal_api.retry_times'),
71	                (int) Config::string('ecnavi.app.internal_api.retry_delay'),
72	                throw: false
73	            )
74	            ->timeout((int) Config::string('ecnavi.app.internal_api.timeout'))
75	            ->connectTimeout((int) Config::string('ecnavi.app.internal_api.connect_timeout'))
76	            ->replaceHeaders([
77	                'X-POINT-API-SIGNATURE' => $signature,
78	            ])
79	            ->withOptions($options)
80	            ->post(self::ECNAVI_INTERNAL_API_PATH.$path, $requestParams);
81	
82	        if ($response->status() !== 200) {
83	            $this->handleErrorResponse($response);
84	        }
85	
86	        /** @var array{pointId: int, message: string} $jsonResponse */
87	        $jsonResponse = $response->json();
88	
89	        return [
90	            'statusCode' => $response->status(),
91	            'body' => $jsonResponse,
92	        ];
93	    }
94	
95	    private function handleErrorResponse(Response $response): void
96	    {
97	        $statusExceptionMapping = [
98	            401 => UnauthorizedException::class,
99	            403 => ForbiddenException::class,
100	            404 => NotFoundException::class,
101	            405 => MethodNotAllowedException::class,
102	            500 => InternalServerErrorException::class,
103	            503 => ServiceUnavailableException::class,
104	        ];
105	
106	        foreach ($statusExceptionMapping as $status => $exception) {
107	            if ($response->status() === $status) {
108	                throw new $exception(json_encode($response->json(), JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR));
109	            }
110	        }
111	
112	        $badRequestExceptionMapping = [
113	            10 => InvalidParameterException::class,
114	            20 => TemplateNotFoundException::class,
115	            30 => ClientNotFoundException::class,
116	            40 => PointDuplicateException::class,
117	            50 => MaxPointValueException::class,
118	            60 => AllianceUserNotFoundException::class,
119	            70 => PointIdNotFoundException::class,
120	            80 => AlreadyGrantedException::class,
121	        ];
122	
123	        if ($response->status() === 400) {
124	            /** @var array{code: int, message: string} $jsonResponse */
125	            $jsonResponse = $response->json();
126	            foreach ($badRequestExceptionMapping as $code => $exception) {
127	                if ($jsonResponse['code'] === $code) {
128	                    throw new $exception(json_encode($response->json(), JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR));
129	                }
130	            }
131	        }
132	
133	        throw new UnexpectedException(json_encode($response->json(), JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR));
134	    }
135	}
