3	namespace App\Services\Web\Answer;
4	
5	use App\Http\Requests\SurveyPostRequest\Type as SurveyPostRequestType;
6	use App\Models\AnswerDeviceType;
7	use App\Models\AnswerSource;
8	use App\Models\AnswerType;
9	use App\Models\Delivery;
10	use App\Services\Common\Util\S3ClientUtils;
11	use App\Services\Web\Assignment\AssignmentSettingAnswerCreator;
12	use App\Services\Web\SurveyService\Exceptions\AlreadyAnsweredException;
13	use App\Services\Web\SurveyService\Exceptions\InvalidAnswerDataException;
14	use App\Types\QuestionType;
15	use Aws\S3\S3Client;
16	use Detection\MobileDetect;
17	use Exception;
18	use Illuminate\Database\UniqueConstraintViolationException;
19	use Illuminate\Support\Facades\Config;
20	use Illuminate\Support\Facades\DB;
21	
22	/**
23	 * @phpstan-import-type SurveyPostParams from SurveyPostRequestType
24	 * @phpstan-import-type Question from QuestionType
25	 * @phpstan-type FileAnswerData array{ name: string, type: string, content: array{ key: string, tempKey: string } }[]
26	 * @phpstan-type AnswerData string|array{ file: FileAnswerData }
27	 * @phpstan-type Answer array<string, AnswerData>
28	 */
29	class AnswerCreator
30	{
31	    private S3Client $s3;
32	
33	    private string $surveyAnswerFileBucket;
34	
35	    private string $temporarySurveyAnswerFileBucket;
36	
37	    const SURVEY_SOURCE_SESSION_KEY = 'source_%s';
38	
39	    // ユーザーが設問毎に一度にアップロード可能な最大枚数
40	    private const int MAX_FILE_COUNT = 5;
41	
42	    public function __construct(
43	        private readonly MobileDetect $mobileDetect,
44	        private readonly AssignmentSettingAnswerCreator $assignmentSettingAnswerCreator,
45	    ) {
46	        $this->s3 = S3ClientUtils::loadClient();
47	        $this->surveyAnswerFileBucket = Config::string('orsay.s3.survey-answer-file');
48	        $this->temporarySurveyAnswerFileBucket = Config::string('orsay.s3.temporary-survey-answer-file');
49	    }
50	
51	    /**
52	     * @param  SurveyPostParams  $answerParams
53	     */
54	    public function exec(Delivery $delivery, int $userId, array $answerParams): void
55	    {
56	        try {
57	            DB::transaction(function () use ($delivery, $userId, $answerParams) {
58	                $question = $delivery->survey->question;
59	                assert(is_string($question));
60	
61	                $jsonDecoder = new QuestionJsonDecoder($question, $answerParams['answer_data']);
62	                $pagedUserQuestions = $jsonDecoder->createPagedUserQuestions();
63	                $triggers = $jsonDecoder->createTriggers();
64	
65	                $flatten = new UserQuestionFlatter($pagedUserQuestions);
66	                $userQuestionsWithInvisible = $flatten->flatten();
67	
68	                $trimmer = new UserQuestionTrimmer($userQuestionsWithInvisible);
69	                $userQuestions = $trimmer->trim();
70	
71	                $answerTypeGetter = new AnswerTypeGetter($userQuestions, $triggers);
72	                $answerType = $answerTypeGetter->getAnswerType();
73	
74	                $this->processAnswerData($answerParams['answer_data'], $question);
75	
76	                $answer = $delivery->answers()->create([
77	                    'answer_data' => $answerParams['answer_data'],
78	                    'user_id' => $userId,
79	                    'answer_type_id' => $this->getAnswerTypeId($answerType),
80	                ]);
81	
82	                $this->assignmentSettingAnswerCreator->exec($delivery, $answer);
83	
84	                $answer->answerAnalysis()->create([
85	                    'answer_device_type_id' => $this->mobileDetect->isMobile() ? AnswerDeviceType::getSpAnswerDeviceTypeId() : AnswerDeviceType::getPcAnswerDeviceTypeId(),
86	                    'answer_source_id' => AnswerSource::whereName(session(sprintf(self::SURVEY_SOURCE_SESSION_KEY, $delivery->survey->survey_uuid)))->first()?->id,
87	                ]);
88	
89	                // ポイント数が0の場合、ポイント履歴へ反映しない。
90	                // ポイントログの作成自体が不要であり、その前段階の付与待ちリストへの記載自体を省略する。
91	                $pointValue = $this->getPointValue($delivery, $answerType);
92	                if ($pointValue > 0) {
93	                    $answer->pointGrantWaiting()->create([
94	                        'user_id' => $userId,
95	                        'point_id' => $this->getPointId($delivery, $answerType),
96	                        'point_value' => $pointValue,
97	                    ]);
98	                }
99	            });
100	        } catch (Exception $e) {
101	            $question = $delivery->survey->question;
102	            assert(is_string($question));
103	            $this->handleException($answerParams['answer_data'], $question);
104	
105	            // 回答済みの場合は、AlreadyAnsweredException に例外を切り替えて投げる
106	            $message = $e->getMessage();
107	            if ($e instanceof UniqueConstraintViolationException
108	                && str_contains($message, '1062 Duplicate entry')
109	                && str_contains($message, 'answers.answers_delivery_id_user_id_unique')
110	            ) {
111	                throw new AlreadyAnsweredException("ユーザ(ID: {$userId})は既に配信(ID: {$delivery->id})に回答済みです。", 0, $e);
112	            }
113	
114	            throw $e;
115	        }
116	    }
117	
118	    /**
119	     * @param  AnswerType::TYPE_FULL|AnswerType::TYPE_PARTIAL  $answerType
120	     */
121	    private function getAnswerTypeId(string $answerType): ?int
122	    {
123	        return AnswerType::whereName($answerType)->first()?->id;
124	    }
125	
126	    /**
127	     * @param  AnswerType::TYPE_FULL|AnswerType::TYPE_PARTIAL  $answerType
128	     */
129	    private function getPointValue(Delivery $delivery, string $answerType): ?int
130	    {
131	        return match ($answerType) {
132	            AnswerType::TYPE_FULL => $delivery->survey->full_answer_point_value,
133	            AnswerType::TYPE_PARTIAL => $delivery->survey->partial_answer_point_value,
134	        };
135	    }
136	
137	    /**
138	     * @param  AnswerType::TYPE_FULL|AnswerType::TYPE_PARTIAL  $answerType
139	     */
140	    private function getPointId(Delivery $delivery, string $answerType): ?int
141	    {
142	        return match ($answerType) {
143	            AnswerType::TYPE_FULL => $delivery->survey->full_answer_point_id,
144	            AnswerType::TYPE_PARTIAL => $delivery->survey->partial_answer_point_id,
145	        };
146	    }
147	
148	    private function processAnswerData(string $answerData, string $question): void
149	    {
150	        /**
151	         * @var Question $parsedQuestion
152	         */
153	        $parsedQuestion = json_decode($question, true);
154	        /**
155	         * @var Answer $parsedAnswerData
156	         */
157	        $parsedAnswerData = json_decode($answerData, true);
158	        foreach ($parsedQuestion['pages'] as $page) {
159	            foreach ($page['elements'] as $element) {
160	                $questionName = $element['name'];
161	                // getAnswerType で全ての設問に回答していることを確認しているため、設問が回答データに含まれていない場合はスキップする
162	                if (! isset($parsedAnswerData[$questionName])) {
163	                    continue;
164	                }
165	
166	                // 設問タイプ毎のバリデーション処理はここに追加する
167	                if ($element['type'] === 'image-file') {
168	                    $this->validateFileAnswerData($parsedAnswerData[$questionName]);
169	                    assert(isset($parsedAnswerData[$questionName]['file']));
170	                    $this->copyAnswerFiles($parsedAnswerData[$questionName]['file']);
171	                }
172	            }
173	        }
174	    }
175	
176	    /**
177	     * @param  AnswerData  $answerData
178	     */
179	    private function validateFileAnswerData(string|array $answerData): void
180	    {
181	        $this->validateFileUploaded($answerData);
182	        assert(isset($answerData['file']));
183	        $files = $answerData['file'];
184	        $this->validateFileCount($files);
185	        $this->validateFilesExistInS3($files);
186	    }
187	
188	    /**
189	     * @param  AnswerData  $answerData
190	     */
191	    private function validateFileUploaded(string|array $answerData): void
192	    {
193	        if (empty($answerData['file'])) {
194	            throw new InvalidAnswerDataException('ファイルがアップロードされていません。');
195	        }
196	    }
197	
198	    /**
199	     * @param  FileAnswerData  $files
200	     */
201	    private function validateFileCount(array $files): void
202	    {
203	        if (count($files) > self::MAX_FILE_COUNT) {
204	            throw new InvalidAnswerDataException('アップロードできるファイルは5件までです');
205	        }
206	    }
207	
208	    /**
209	     * @param  FileAnswerData  $files
210	     */
211	    private function validateFilesExistInS3(array $files): void
212	    {
213	        foreach ($files as $file) {
214	            if (! $this->s3->doesObjectExist($this->temporarySurveyAnswerFileBucket, $file['content']['tempKey'])) {
215	                throw new InvalidAnswerDataException('ファイルがアップロードされていません。');
216	            }
217	        }
218	    }
219	
220	    /**
221	     * @param  FileAnswerData  $files
222	     */
223	    private function copyAnswerFiles(array $files): void
224	    {
225	        foreach ($files as $file) {
226	            $this->s3->copyObject([
227	                'Bucket' => $this->surveyAnswerFileBucket,
228	                'Key' => $file['content']['key'],
229	                'CopySource' => "{$this->temporarySurveyAnswerFileBucket}/{$file['content']['tempKey']}",
230	            ]);
231	        }
232	    }
233	
234	    private function handleException(string $answerData, string $question): void
235	    {
236	        /**
237	         * @var Question $parsedQuestion
238	         */
239	        $parsedQuestion = json_decode($question, true);
240	        /**
241	         * @var Answer $parsedAnswerData
242	         */
243	        $parsedAnswerData = json_decode($answerData, true);
244	        foreach ($parsedQuestion['pages'] as $page) {
245	            foreach ($page['elements'] as $element) {
246	                $questionName = $element['name'];
247	                if (! isset($parsedAnswerData[$questionName])) {
248	                    continue;
249	                }
250	
251	                if ($element['type'] === 'image-file') {
252	                    $this->deleteAnswerFiles($parsedAnswerData[$questionName]);
253	                }
254	            }
255	        }
256	    }
257	
258	    /**
259	     * @param  AnswerData  $answerData
260	     */
261	    private function deleteAnswerFiles(string|array $answerData): void
262	    {
263	        if (isset($answerData['file'])) {
264	            foreach ($answerData['file'] as $file) {
265	                if ($this->s3->doesObjectExist($this->surveyAnswerFileBucket, $file['content']['key'])) {
266	                    $this->s3->deleteObject([
267	                        'Bucket' => $this->surveyAnswerFileBucket,
268	                        'Key' => $file['content']['key'],
269	                    ]);
270	                }
271	            }
272	        }
273	    }
274	}
