13	     * @template TReturn of mixed
14	     *
15	     * Execute a Closure within a transaction.
16	     *
17	     * @param  (\Closure(static): TReturn)  $callback
18	     * @param  int  $attempts
19	     * @return TReturn
20	     *
21	     * @throws \Throwable
22	     */
23	    public function transaction(Closure $callback, $attempts = 1)
24	    {
25	        for ($currentAttempt = 1; $currentAttempt <= $attempts; $currentAttempt++) {
26	            $this->beginTransaction();
27	
28	            // We'll simply execute the given callback within a try / catch block and if we
29	            // catch any exception we can rollback this transaction so that none of this
30	            // gets actually persisted to a database or stored in a permanent fashion.
31	            try {
32	                $callbackResult = $callback($this);
33	            }
34	
35	            // If we catch an exception we'll rollback this transaction and try again if we
36	            // are not out of attempts. If we are out of attempts we will just throw the
37	            // exception back out, and let the developer handle an uncaught exception.
38	            catch (Throwable $e) {
39	                $this->handleTransactionException(
40	                    $e, $currentAttempt, $attempts
41	                );
42	
43	                continue;
44	            }
45	
46	            $levelBeingCommitted = $this->transactions;
47	
48	            try {
49	                if ($this->transactions == 1) {
50	                    $this->fireConnectionEvent('committing');
51	                    $this->getPdo()->commit();
52	                }
53	
54	                $this->transactions = max(0, $this->transactions - 1);
55	            } catch (Throwable $e) {
56	                $this->handleCommitTransactionException(
57	                    $e, $currentAttempt, $attempts
58	                );
59	
60	                continue;
61	            }
62	
63	            $this->transactionsManager?->commit(
64	                $this->getName(),
65	                $levelBeingCommitted,
66	                $this->transactions
67	            );
68	
69	            $this->fireConnectionEvent('committed');
70	
71	            return $callbackResult;
72	        }
73	    }
