75	    /**
76	     * Handle an exception encountered when running a transacted statement.
77	     *
78	     * @param  \Throwable  $e
79	     * @param  int  $currentAttempt
80	     * @param  int  $maxAttempts
81	     * @return void
82	     *
83	     * @throws \Throwable
84	     */
85	    protected function handleTransactionException(Throwable $e, $currentAttempt, $maxAttempts)
86	    {
87	        // On a deadlock, MySQL rolls back the entire transaction so we can't just
88	        // retry the query. We have to throw this exception all the way out and
89	        // let the developer handle it in another way. We will decrement too.
90	        if ($this->causedByConcurrencyError($e) &&
91	            $this->transactions > 1) {
92	            $this->transactions--;
