public function uploadedFileUrl(SurveyUploadedFileUrlRequest $request, string $surveyUuid, string $questionId, string $fileId): JsonResponse
{
    /**
     * @var SurveyUploadedFileUrlParams $validated
     */
    $validated = $request->validated();
    $userId = Auth::id();
    assert(is_int($userId));
    try {
        $delivery = $this->validDeliveryFinder->exec($surveyUuid, $userId);
        $url = $this->surveyAnswerFileUrlGenerator->exec($delivery, $userId, (int) $questionId, (int) $fileId, $validated);
    } catch (BaseException $e) {
        return response()->json([
            'errors' => [$e->getErrorMessage()],
        ], $e->getStatusCode());
    }

    return response()->json([
        'url' => $url,
    ]);
}

public function storeProgressAnswer(SurveyProgressPostRequest $request, string $surveyUuid): SymfonyResponse
{
    /**
     * @var SurveyProgressPostParams $validated
     */
    $validated = $request->validated();
    $userId = Auth::id();
    assert(is_int($userId));
    try {
        $this->userAnswerProgressCacheManager->put($userId, $surveyUuid, $validated);
    } catch (Exception $e) {
        // エラーログだけ吐いて続行する
        $this->logger->error('回答途中保存データの保存に失敗しました。', ['error' => "$e"]);
    }

    return response('', 200);
}

