public function answer(Request $request, string $surveyUuid): Response|SymfonyResponse
{
    $userId = Auth::id();
    assert(is_int($userId));
    try {
        $delivery = $this->validDeliveryFinder->exec($surveyUuid, $userId);
        $progressAnswerData = $this->userAnswerProgressCacheManager->get($userId, $surveyUuid);
    } catch (BaseException $e) {
        return $this->renderError($e, $request);
    } catch (InvalidArgumentException $e) {
        // エラーログだけ吐いて続行する
        $this->logger->error('回答途中保存データの読み込みに失敗しました。', ['error' => "$e"]);
    }

    assert(is_string($delivery->survey->question));
    $mapping = $this->mappingBuilder->build($delivery->survey->affiliateItemSurvey?->affiliateItem?->ecnavi_affiliate_item_id);

    return Inertia::render('Surveys/Answer', [
        'name' => $delivery->survey->name,
        'surveyUuid' => $delivery->survey->survey_uuid,
        'question' => $this->questionBinder->bindItem(
            $delivery->survey->id,
            $delivery->survey->question,
            $mapping,
        ),
        'fullAnswerDestinationUrl' => $this->surveyService->getFullAnswerDestinationUrl($delivery->survey),
        'partialAnswerDestinationUrl' => $this->surveyService->getPartialAnswerDestinationUrl(),
        'isAffiliate' => $delivery->survey->surveyType->name === SurveyType::TYPE_AFFILIATE,
        'ecnaviBaseUrl' => Config::string('ecnavi.app.base_url'),
        'ecnaviAffiliateItem' => $mapping,
        'progressAnswerData' => $progressAnswerData ?? null,
    ]);
}

